/**
 * worker/sweeps.ts — the background sweep runner that keeps housekeeping off
 * the job-claim path. Real timers with tiny intervals (tens of ms) — the
 * behaviours under test are ordering/overlap/limits, not wall-clock accuracy.
 */

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const quiet = { log: () => {}, logError: () => {} };

test("a sweep never overlaps itself: a run longer than its interval is not started again until it settles", async () => {
  let concurrent = 0;
  let maxConcurrent = 0;
  let runs = 0;
  const runner = new SweepRunner({ maxConcurrent: 4, ...quiet });
  runner.register({
    name: "slow",
    intervalMs: 10,
    fn: async () => {
      runs++;
      concurrent++;
      maxConcurrent = Math.max(maxConcurrent, concurrent);
      await sleep(60);
      concurrent--;
    },
  });
  runner.start();
  await sleep(250);
  await runner.stop(500);
  assert.equal(maxConcurrent, 1, "never two instances of one sweep");
  assert.ok(runs >= 2 && runs <= 5, `ran ${runs} times in 250ms with 60ms runs`);
});

test("global concurrency cap bounds how many different sweeps run at once; all still get to run", async () => {
  let concurrent = 0;
  let maxConcurrent = 0;
  const ran = new Set<string>();
  const runner = new SweepRunner({ maxConcurrent: 2, ...quiet });
  for (let i = 0; i < 6; i++) {
    runner.register({
      name: `s${i}`,
      intervalMs: 10_000,
      fn: async () => {
        ran.add(`s${i}`);
        concurrent++;
        maxConcurrent = Math.max(maxConcurrent, concurrent);
        await sleep(30);
        concurrent--;
      },
    });
  }
  runner.start();
  await sleep(300);
  await runner.stop(500);
  assert.equal(maxConcurrent, 2);
  assert.equal(ran.size, 6, "every registered sweep ran at boot");
});

