// The single Cyrus scheduler entry point: same sweeps, cadences, timeouts and off-switches the platform worker used to
// register inline, and the platform worker registers them with one call.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { registerCyrusSweeps, startCyrusSoundRelay } from "../lib/cyrus/worker/schedule";
import { setHost, type CyrusHost } from "../lib/cyrus/host";

type Def = { name: string; intervalMs: number; fn: () => Promise<unknown>; timeoutMs?: number };
const collect = (env: Record<string, string | undefined> = {}) => {
  const defs: Def[] = [];
  registerCyrusSweeps({ register: (d) => { defs.push(d); return null; } }, env);
  return defs;
};
const MIN = 60_000;

describe("registerCyrusSweeps", () => {
  it("registers exactly the five Cyrus sweeps with the original cadence and timeouts", () => {
    const d = collect();
    assert.deepEqual(
      d.map((x) => [x.name, x.intervalMs, x.timeoutMs]),
      [
        ["modbuilder-sync", 20_000, 2 * MIN],
        ["cyrus-tokens", 5 * MIN, 3 * MIN],
        ["cyrus-lifecycle", 5 * MIN, undefined],
        ["cyrus-compat-watch", 6 * 60 * MIN, undefined],
        ["cyrus-testflight-gate", 2 * MIN, undefined],
      ],
    );
  });
  it("lifecycle sweeps are fire-and-forget through the host and swallow errors; build sync passes the result through", async () => {
    const calls: string[] = [];
    const restore = setHost({
      worker: {
        modLifecycleSweep: async () => { calls.push("life"); throw new Error("boom"); },
        modCompatWatchSweep: async () => { calls.push("compat"); },
        syncModBuilds: async () => { calls.push("sync"); },
      },
    } as unknown as CyrusHost);
    const origErr = console.error; const errs: unknown[][] = [];
    console.error = (...a: unknown[]) => { errs.push(a); };
    try {
      const d = collect();
      const by = Object.fromEntries(d.map((x) => [x.name, x]));
      await by["modbuilder-sync"].fn();
      await by["cyrus-lifecycle"].fn(); // returns before the sweep settles (void)
      await by["cyrus-compat-watch"].fn();
      await new Promise((r) => setTimeout(r, 10));
      assert.deepEqual(calls.sort(), ["compat", "life", "sync"]);
      assert.equal(errs.length, 1);
      assert.equal(errs[0][0], "[cyrus-lifecycle] sweep error");
    } finally { console.error = origErr; restore(); }
  });
  it("the Test Flight gate returns before any import or database read unless CYRUS_TESTFLIGHT_GATE=1", async () => {
    const gate = collect({}).find((x) => x.name === "cyrus-testflight-gate")!;
    assert.equal(await gate.fn(), undefined);
  });
});

describe("startCyrusSoundRelay", () => {
  it("is inert unless CYRUS_SOUND_RENDER=ssh and a relay port are set", async () => {
    assert.equal(await startCyrusSoundRelay({}), false);
    assert.equal(await startCyrusSoundRelay({ CYRUS_SOUND_RENDER: "ssh" }), false);
    assert.equal(await startCyrusSoundRelay({ CYRUS_SOUND_RELAY_PORT: "9999" }), false);
  });
});

describe("platform worker wiring", () => {
  const src = readFileSync(path.join(__dirname, "..", "worker", "index.ts"), "utf8");
  it("registers Cyrus with one call and no longer names the sweeps inline", () => {
    assert.equal(src.match(/registerCyrusSweeps\(runner\)/g)?.length, 1);
    for (const n of ["cyrus-tokens", "cyrus-lifecycle", "cyrus-compat-watch", "cyrus-testflight-gate", "modbuilder-sync"]) {
      assert.ok(!src.includes(`add("${n}"`), `${n} still registered inline`);
    }
    assert.ok(!/sweepCyrusTokens|cyrusLifecycleSweep|sweepModBuilds/.test(src));
  });
});
EOF
(/opt/nxeon/scripts/devhost test test/cyrus-worker-schedule.test.ts test/cyrus-host-seam.test.ts 2>&1 | tail -40)

