// CyrusConfig: every machine path, remote host and credentials-file location Cyrus needs, in ONE place, read from the
// environment with the defaults Nxeon runs with today. Moving Cyrus to other servers means setting these variables
// (or replacing this file), never editing feature code. Pure (no imports, no I/O): safe in the browser bundle, where
// process.env is empty and every value is simply its default.
// The `guest` block is the layout INSIDE a customer game server; it must match whatever installs the server (inside
// Nxeon: lib/mods and the Minecraft image), so change it only together with that.

type Env = Record<string, string | undefined>;
const pick = (env: Env, name: string, dflt: string): string => (env[name] && env[name]!.trim() ? env[name]!.trim() : dflt);
const trimSlash = (p: string) => (p.length > 1 ? p.replace(/\/+$/, "") : p);

export type CyrusConfig = {
  /** ssh target of the build / render / Test Flight host (CYRUS_BUILD_HOST; default Nxeon's node-2). */
  buildHost: string;
  /** Working roots on that host. */
  testFlightRoot: string; // CYRUS_TESTFLIGHT_ROOT
  meshgenRoot: string; // CYRUS_MESHGEN_ROOT
  blenderDir: string; // CYRUS_BLENDER_DIR
  soundRenderRoot: string; // CYRUS_SOUND_RENDER_ROOT
  soundLibraryDir: string; // CYRUS_SOUND_LIBRARY_DIR
  soundFfmpegDir: string; // CYRUS_SOUND_FFMPEG_DIR
  /** On the machine that runs the web/worker process. */
  modbuildDir: string; // NXEON_MODBUILD_DIR (built jars, uploads, attachments, media)
  importDir: string; // CYRUS_IMPORT_DIR (quarantined plugin imports)
  /** Credentials file of the build service client (MODBUILDER_URL / MODBUILDER_API_KEY fallback). */
  modbuilderEnvFile: string; // MODBUILDER_ENV_FILE
  /** Paths inside a customer game server. */
  guest: {
    mcBase: string; // CYRUS_GUEST_MC_BASE
    stateDir: string; // CYRUS_GUEST_STATE_DIR: Cyrus' own records, journals and backups
    modsBackupDir: string; // CYRUS_GUEST_MODS_BACKUP_DIR: the platform mod engine's rotating backups
  };
};

export function cyrusConfig(env: Env = typeof process !== "undefined" ? process.env : {}): CyrusConfig {
  const stateDir = trimSlash(pick(env, "CYRUS_GUEST_STATE_DIR", "/root/.nxeon-cyrus"));
  return {
    buildHost: pick(env, "CYRUS_BUILD_HOST", "root@178.63.94.114"),
    testFlightRoot: trimSlash(pick(env, "CYRUS_TESTFLIGHT_ROOT", "/tank/nxeon-build/tmp/testflight")),
    meshgenRoot: trimSlash(pick(env, "CYRUS_MESHGEN_ROOT", "/tank/nxeon-build/tmp/meshgen")),
    blenderDir: trimSlash(pick(env, "CYRUS_BLENDER_DIR", "/tank/nxeon-build/tmp/blender-poc/blender-5.2.2-linux-x64")),
    soundRenderRoot: trimSlash(pick(env, "CYRUS_SOUND_RENDER_ROOT", "/tank/nxeon-build/tmp/sound-render")),
    soundLibraryDir: trimSlash(pick(env, "CYRUS_SOUND_LIBRARY_DIR", "/tank/nxeon-build/tmp/sound-library/files")),
    soundFfmpegDir: trimSlash(pick(env, "CYRUS_SOUND_FFMPEG_DIR", "/tank/nxeon-build/tmp/ffmpeg/current/bin")),
    modbuildDir: pick(env, "NXEON_MODBUILD_DIR", "/var/lib/nxeon/modbuilds"),
    importDir: pick(env, "CYRUS_IMPORT_DIR", "/var/lib/nxeon/cyrus-imports"),
    modbuilderEnvFile: pick(env, "MODBUILDER_ENV_FILE", "/etc/nxeon/modbuilder.env"),
    guest: {
      mcBase: trimSlash(pick(env, "CYRUS_GUEST_MC_BASE", "/opt/mc")),
      stateDir,
      modsBackupDir: trimSlash(pick(env, "CYRUS_GUEST_MODS_BACKUP_DIR", "/root/.nxeon-mods/backups")),
    },
  };
}
