    assert.equal(c.buildHost, "root@178.63.94.114");
    assert.equal(c.testFlightRoot, "/tank/nxeon-build/tmp/testflight");
    assert.equal(c.meshgenRoot, "/tank/nxeon-build/tmp/meshgen");
    assert.equal(c.blenderDir, "/tank/nxeon-build/tmp/blender-poc/blender-5.2.2-linux-x64");
    assert.equal(c.soundRenderRoot, "/tank/nxeon-build/tmp/sound-render");
    assert.equal(c.soundLibraryDir, "/tank/nxeon-build/tmp/sound-library/files");
    assert.equal(c.soundFfmpegDir, "/tank/nxeon-build/tmp/ffmpeg/current/bin");
  });
  it("local dirs and credentials file", () => {
    assert.equal(c.modbuildDir, "/var/lib/nxeon/modbuilds");
    assert.equal(c.importDir, "/var/lib/nxeon/cyrus-imports");
    assert.equal(c.modbuilderEnvFile, "/etc/nxeon/modbuilder.env");
  });
  it("guest server layout", () => {
    assert.deepEqual(c.guest, { mcBase: "/opt/mc", stateDir: "/root/.nxeon-cyrus", modsBackupDir: "/root/.nxeon-mods/backups" });
  });
  it("blank values fall back to the default", () => {
    assert.equal(cyrusConfig({ CYRUS_BUILD_HOST: "  ", CYRUS_GUEST_MC_BASE: "" }).buildHost, "root@178.63.94.114");
    assert.equal(cyrusConfig({ CYRUS_GUEST_MC_BASE: "" }).guest.mcBase, "/opt/mc");
  });
});

