      CYRUS_SOUND_RENDER_ROOT: "/srv/snd", CYRUS_SOUND_LIBRARY_DIR: "/srv/lib", CYRUS_SOUND_FFMPEG_DIR: "/srv/ff",
      NXEON_MODBUILD_DIR: "/data/builds", CYRUS_IMPORT_DIR: "/data/imports", MODBUILDER_ENV_FILE: "/etc/cyrus/mb.env",
      CYRUS_GUEST_MC_BASE: "/srv/mc/", CYRUS_GUEST_STATE_DIR: "/srv/.cyrus/", CYRUS_GUEST_MODS_BACKUP_DIR: "/srv/.mods/bk",
    });
    assert.equal(c.buildHost, "cyrus@render.example");
    assert.equal(c.testFlightRoot, "/srv/tf");
    assert.equal(c.soundFfmpegDir, "/srv/ff");
    assert.equal(c.modbuildDir, "/data/builds");
    assert.equal(c.modbuilderEnvFile, "/etc/cyrus/mb.env");
    assert.deepEqual(c.guest, { mcBase: "/srv/mc", stateDir: "/srv/.cyrus", modsBackupDir: "/srv/.mods/bk" });
  });
});

describe("no hardcoded host paths in Cyrus feature code", () => {
  const ROOT = path.resolve(__dirname, "..");
  const walk = (d: string, out: string[] = []): string[] => {
    for (const n of readdirSync(d)) {
      const p = path.join(d, n);
      if (statSync(p).isDirectory()) walk(p, out); else if (/\.(ts|tsx)$/.test(n)) out.push(p);
    }
    return out;
  };
  const BANNED = /178\.63\.94\.114|\/tank\/nxeon-build|["'`]\/opt\/mc["'`\/]|\/root\/\.nxeon-cyrus|\/root\/\.nxeon-mods\/backups|\/etc\/nxeon\/|\/var\/lib\/nxeon\/|claudebox\.env/;
  // Whole-file allowances: the config itself, and files whose literals are user-facing guidance text, not paths we use.
  const ALLOW = new Set(["lib/cyrus/config.ts"]);
  it("lib/cyrus, lib/modbuilder and the Cyrus workers name them only through lib/cyrus/config.ts", () => {
    const files = [...walk(path.join(ROOT, "lib", "cyrus")), ...walk(path.join(ROOT, "lib", "modbuilder")), path.join(ROOT, "worker", "cyrus-delivery.ts"), path.join(ROOT, "worker", "cyrus-lifecycle.ts")];
    const hits: string[] = [];
    for (const f of files) {
      const rel = path.relative(ROOT, f).split(path.sep).join("/");
      if (ALLOW.has(rel)) continue;
      readFileSync(f, "utf8").split("\n").forEach((line, i) => {
        if (/^\s*(\/\/|\*|\/\*)/.test(line)) return; // comments describe, they do not configure
        if (BANNED.test(line)) hits.push(`${rel}:${i + 1}: ${line.trim().slice(0, 140)}`);
      });
    }
    assert.deepEqual(hits, [], "use cyrusConfig() (lib/cyrus/config.ts) instead of a literal path or host");
  });
});
