/**
 * The installer's view of a game server's filesystem.
 *
 * Two implementations:
 *  - worker/mods-guest-ssh.ts — the real thing: one SSH connection (management
 *    key first, root password fallback — the same order lib/sftp.ts uses),
 *    SFTP for reads/writes, a handful of fixed, quoted shell verbs for
 *    mkdir/mv/rm/chown.
 *  - LocalGuestFs below — maps the guest's absolute paths into a local
 *    directory. Used by the unit tests and by SANDBOX mode, where the worker
 *    runs the REAL resolve/download/place/apply pipeline against a fake guest
 *    tree under NXEON_SANDBOX_GUEST_DIR (default /tmp/nxeon-sandbox-guests/<id>)
 *    instead of pretending. That fake tree is seeded per family so detect()
 *    finds a plausible server.
 */
import { promises as fsp } from "node:fs";
import path from "node:path";
import { isSafeAbs } from "./paths";

export type GuestStat = { type: "file" | "dir"; size: number };

export interface GuestFs {
  readonly kind: "ssh" | "local";
  stat(p: string): Promise<GuestStat | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  /** Creates parent directories. */
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  /** Move, overwriting a file at `to`. Creates the destination's parent. */
  rename(from: string, to: string): Promise<void>;
  /** File or directory (recursive). Missing is not an error. */
  remove(p: string): Promise<void>;
  /** Entry names; [] when missing. */
  list(dir: string): Promise<string[]>;
  /** Best-effort: give `paths` the owner/group of `ref` (real guests only). */
  chownLike(ref: string, paths: string[]): Promise<void>;
  /** Copy a file (used for backups). */
  copy(from: string, to: string): Promise<void>;
}

function assertAbs(p: string) {
  if (!isSafeAbs(p)) throw new Error(`unsafe guest path: ${p}`);
}

export class LocalGuestFs implements GuestFs {
  readonly kind = "local" as const;
  constructor(readonly root: string) {}

  private map(p: string): string {
    assertAbs(p);
    const full = path.join(path.resolve(this.root), p);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("path escapes the fake guest root");
    return full;
  }

  async stat(p: string): Promise<GuestStat | null> {
    try {
      const s = await fsp.lstat(this.map(p));
      if (s.isSymbolicLink()) return null;
      return { type: s.isDirectory() ? "dir" : "file", size: s.size };
    } catch {
      return null;
    }
  }
  async readFile(p: string, maxBytes = 64 * 1024 * 1024): Promise<Buffer | null> {
    const s = await this.stat(p);
    if (!s || s.type !== "file" || s.size > maxBytes) return null;
    return fsp.readFile(this.map(p));
  }
  async writeFile(p: string, data: Buffer): Promise<void> {
    const f = this.map(p);
    await fsp.mkdir(path.dirname(f), { recursive: true });
    await fsp.writeFile(f, data);
  }
  async mkdirp(p: string): Promise<void> {
    await fsp.mkdir(this.map(p), { recursive: true });
  }
  async rename(from: string, to: string): Promise<void> {
    const t = this.map(to);
    await fsp.mkdir(path.dirname(t), { recursive: true });
