// How a managed plugin's jar gets onto (or off) a server. INJECTABLE: ensure/release (./service) only talk to this
// interface, so the logic is tested with memoryInstaller(). The real one (engineManagedInstaller) places the jar
// through the shared Mods engine (lib/mods/engine.ts: guest state file, backup, staged write, rollback) and is
// OFF unless CYRUS_MANAGED_PLUGINS_REAL=1. Called (flag-gated) by lib/cyrus/assets/deliver-worker.ts from the worker (docs "Cyrus asset slice (R1)").
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import path from "node:path";
import type { CatalogEntry } from "./catalog";
import { installOrUpdate, uninstall, type EngineDeps } from "../../mods/engine";
import { minecraftInstaller } from "../../mods/installers/minecraft";
import type { CatalogFacts, FamilyInstaller, Resolution, ServerFacts } from "../../mods/types";
import type { GuestFs } from "../../mods/guest-fs";
import { FetchError } from "../../mods/safe-fetch";

export type InstallReq = { serverId: string; entry: CatalogEntry; previousVersion: string | null };
export type RemoveReq = { serverId: string; key: string; pluginName: string | null; version: string | null };
export type InstallOutcome = { ok: true; version: string; sha256: string; notes?: string[] } | { ok: false; error: string };
export type RemoveOutcome = { ok: true; notes?: string[] } | { ok: false; error: string };

export interface ManagedInstaller {
  install(req: InstallReq): Promise<InstallOutcome>;
  remove(req: RemoveReq): Promise<RemoveOutcome>;
}

/** In-memory fake for tests and the sandbox: records what would be on each server. */
export function memoryInstaller(opts: { fail?: (op: "install" | "remove", req: InstallReq | RemoveReq) => string | null } = {}) {
  const servers = new Map<string, Map<string, { version: string; sha256: string }>>();
  const calls: { op: "install" | "remove"; serverId: string; key: string; version: string | null }[] = [];
  const inst: ManagedInstaller & { servers: typeof servers; calls: typeof calls } = {
    servers,
    calls,
    async install(req) {
      calls.push({ op: "install", serverId: req.serverId, key: req.entry.key, version: req.entry.version });
      const err = opts.fail?.("install", req);
      if (err) return { ok: false, error: err };
      if (!servers.has(req.serverId)) servers.set(req.serverId, new Map());
      servers.get(req.serverId)!.set(req.entry.key, { version: req.entry.version, sha256: req.entry.sha256 });
      return { ok: true, version: req.entry.version, sha256: req.entry.sha256 };
    },
    async remove(req) {
      calls.push({ op: "remove", serverId: req.serverId, key: req.key, version: req.version });
      const err = opts.fail?.("remove", req);
      if (err) return { ok: false, error: err };
      servers.get(req.serverId)?.delete(req.key);
      return { ok: true };
    },
  };
  return inst;
}

export const MANAGED_SOURCE = "nxeon-managed";
export const MANAGED_REAL_FLAG = "CYRUS_MANAGED_PLUGINS_REAL";
export const managedPackageKey = (key: string) => `${MANAGED_SOURCE}:${key}`;

/** Read a catalog artifact from CYRUS_MANAGED_PLUGIN_DIR and verify its sha256 against the pin. */
export async function readManagedArtifact(entry: CatalogEntry, dir = process.env.CYRUS_MANAGED_PLUGIN_DIR || ""): Promise<Buffer> {
  if (!dir || !path.isAbsolute(dir)) throw new Error("CYRUS_MANAGED_PLUGIN_DIR must be an absolute path");
  const p = path.join(dir, entry.artifact);
  if (!p.startsWith(path.resolve(dir) + path.sep)) throw new Error("artifact path escapes the managed plugin dir");
  const bytes = await readFile(p);
  const sha = createHash("sha256").update(bytes).digest("hex");
  if (sha !== entry.sha256) throw new Error(`${entry.key} ${entry.version}: artifact sha256 ${sha} does not match the pin ${entry.sha256}`);
  return bytes;
}

/** The catalogue facts the engine needs for a managed plugin (never listed: there is no GameMod row). */
export function managedFacts(entry: Pick<CatalogEntry, "key" | "displayName">): CatalogFacts {
  return {
    id: `managed:${entry.key}`, gameFamily: "minecraft", slug: entry.key, name: entry.displayName, source: MANAGED_SOURCE, sourceId: entry.key,
    url: null, category: "library", appliesToVariant: null, loaders: ["paper", "purpur"], gameVersions: [], serverSide: "required",
  };
}

/** Engine resolution for a verified artifact: one prefetched plugin jar (no network). */
export function managedResolution(entry: CatalogEntry, bytes: Buffer): Resolution {
  return {
    packages: [{
      key: managedPackageKey(entry.key), name: entry.displayName, version: entry.version, versionId: `${entry.family}:${entry.version}`,
      file: { url: `managed://${entry.key}/${entry.version}`, filename: `${entry.pluginName}.jar`, size: bytes.length, hashes: { sha256: entry.sha256 } },
      placement: "plugin-jar", requires: [], incompatible: [], prefetched: bytes, root: true,
    }],
    notes: [],
  };
}

const noNetwork = async (): Promise<never> => { throw new FetchError("managed plugins never download at install time", "host"); };

/** The Minecraft installer with resolve() replaced by the managed artifact (detect/place/compat unchanged). */
export function managedFamilyInstaller(entry: CatalogEntry, bytes: Buffer): FamilyInstaller {
  return { ...minecraftInstaller, sources: [MANAGED_SOURCE], resolve: async () => managedResolution(entry, bytes), legacyPaths: () => [] };
}

export type GuestOpener = (serverId: string) => Promise<{ fs: GuestFs; server: ServerFacts; close?: () => void }>;

/**
 * Real installer through the Mods engine. Must run where the engine runs (the worker, under its per-server lock).
 * Refuses everything unless CYRUS_MANAGED_PLUGINS_REAL=1.
 */
export function engineManagedInstaller(deps: { open: GuestOpener; readArtifact?: (e: CatalogEntry) => Promise<Buffer>; env?: Record<string, string | undefined> }): ManagedInstaller {
  const env = deps.env ?? process.env;
  const off = () => env[MANAGED_REAL_FLAG] !== "1";
  const OFF = { ok: false as const, error: `managed plugin installs are switched off (${MANAGED_REAL_FLAG} is not 1); nothing was changed` };
  return {
    async install(req) {
      if (off()) return OFF;
      let bytes: Buffer;
      try { bytes = await (deps.readArtifact ?? readManagedArtifact)(req.entry); } catch (e) { return { ok: false, error: (e as Error).message }; }
      const g = await deps.open(req.serverId);
      try {
        const engineDeps: EngineDeps = { fs: g.fs, fetcher: noNetwork };
        const r = await installOrUpdate(managedFamilyInstaller(req.entry, bytes), managedFacts(req.entry), g.server, engineDeps, req.previousVersion ? "update" : "install");
        if (!r.ok) return r;
        return { ok: true, version: req.entry.version, sha256: req.entry.sha256, notes: [...r.changed, ...r.notes] };
      } finally { g.close?.(); }
    },
    async remove(req) {
      if (off()) return OFF;
      const g = await deps.open(req.serverId);
      try {
        const facts = managedFacts({ key: req.key, displayName: req.key });
        // uninstall() never resolves, so the stub entry/bytes are not used for anything but the type.
        const stub = { key: req.key, displayName: req.key, family: "1.21", version: req.version ?? "0", pluginName: req.pluginName ?? req.key, source: "nxeon-built", sourceRef: "-", sha256: "0".repeat(64), artifact: "-", javaRelease: 21 } as CatalogEntry;
        const r = await uninstall(managedFamilyInstaller(stub, Buffer.alloc(0)), facts, g.server, { fs: g.fs, fetcher: noNetwork });
        return r.ok ? { ok: true, notes: [...r.changed, ...r.notes] } : r;
      } finally { g.close?.(); }
    },
  };
}
/**
 * Shared types for the per-game one-click mod installers (lib/mods/installers/*).
 *
 * Shape of an install, for every family that uses this engine:
 *
 *   detect   — look at the server (through a GuestFs) and find WHERE mods go
 *              and what game version / loader it actually runs. If the loader
 *              the mod needs isn't there, stop here with a plain reason.
 *   resolve  — ask the mod's own source for the right build for THIS server
 *              (loader + game version), and walk its required dependencies.
 *              Declared incompatibilities come back too.
 *   download — lib/mods/safe-fetch.ts (allowlisted https, size cap, checksum),
 *              from the NX Labs local mirror first when it holds the file.
 *   place    — pure: bytes → the exact files to write (archives unpacked by
 *              lib/mods/archive.ts with traversal/symlink protection).
 *   apply    — lib/mods/engine.ts: conflict check, backup, staged write,
 *              rollback on failure, per-server state file on the guest.
 *
 * None of this ever reports success for a change it did not make.
 */
import type { Fetcher, Hashes } from "./safe-fetch";
import type { GuestFs } from "./guest-fs";

/** What the catalogue (GameMod) knows about a mod. Never trusted for paths. */
export type CatalogFacts = {
  id: string;
  gameFamily: string;
  slug: string;
  name: string;
  source: string;
  sourceId: string | null;
  url: string | null;
  category: string;
  appliesToVariant: string | null;
  loaders: string[];
  gameVersions: string[];
  serverSide: string | null;
  /** Exact provider version to place (ServerMod.targetVersionId — Cyrus update/rollback). Null/absent = resolver's choice. */
  targetVersionId?: string | null;
};

/** What the DB knows about the server (the guest is asked separately in detect). */
export type ServerFacts = {
  id: string;
  family: string;
  variant: string | null;
  /** VERSION pinned in the server's game config, when it's a real version. */
  pinnedVersion: string | null;
  config: Record<string, unknown> | null;
};

export type Layout = {
  /** Directory everything for this game lives under; ownership reference. */
  base: string;
  /** Named target directories (plugins, mods, datapacks, …). */
  dirs: Record<string, string>;
  /** The game version the server really runs, when it can be read. */
  gameVersion: string | null;
  /** Loader/flavour actually present (e.g. "oxide" vs "carbon"). */
  flavour?: string | null;
};

export type RemoteFile = {
  url: string;
  filename: string;
  size: number | null;
  hashes: Hashes;
  /** Lets the NX Labs mirror find its copy (lib/mods/mirror.ts). */
  mirrorKey?: { source: string; projectId: string | null; versionId: string | null };
  headers?: Record<string, string>;
};

export type ResolvedPackage = {
  /** Unique per server state, e.g. "modrinth:P7dR8mSH", "thunderstore:ValheimModding-Jotunn". */
  key: string;
  name: string;
  version: string;
  versionId?: string | null;
  file: RemoteFile;
  /** Installer-defined placement strategy ("plugin-jar", "mod-jar", "datapack", "bepinex", …). */
  placement: string;
  /** Keys this package needs. */
  requires: string[];
  /** Keys that must NOT be installed alongside this one (declared upstream). */
  incompatible: { key: string; name: string }[];
  /** Bytes already fetched during resolve (e.g. a uMod .cs read for its // Requires: header). */
  prefetched?: Buffer;
  /** True for the mod the customer asked for; false for pulled-in dependencies. */
  root: boolean;
};

export type Resolution = {
  /** Dependency-first order; the last element is the root. */
  packages: ResolvedPackage[];
  notes: string[];
  /**
   * Cyrus lifecycle (2026-10-08, additive): folders whose top-level FILES are copied into the
   * same backup as the files this change replaces (e.g. a plugin's config folder before an
   * update). Backup only: nothing in them is written or removed. Must be under layout.base.
   */
  alsoBackupDirs?: string[];
};

export type PlacedFile = {
  /** Absolute guest path (built with joinUnder — never from raw upstream strings). */
  path: string;
  data: Buffer;
  /** "replace": a file we may overwrite (backed up first), e.g. modpack config overrides. */
  overwrite?: "refuse" | "backup";
};

export type Compat =
  | { verdict: "ok"; detail: string }
  | { verdict: "mismatch"; detail: string }
  | { verdict: "unknown"; detail: string; reason?: "no-list" | "server-unpinned" }
  | { verdict: "unsupported"; detail: string };

export type InstallerCtx = {
  server: ServerFacts;
  layout: Layout;
  fetcher: Fetcher;
