cd /tank/dev-worktrees/cyrus-r22; cat > test/cyrus-host-servers.test.ts <<'EOF'
// Host seam, game-server side: Cyrus places files and opens servers ONLY through host.installs / host.servers, so a
// different host (standalone Cyrus) can supply its own. A recording fake host proves the calls and arguments; the real
// engine path through the Nxeon implementation is covered by test/cyrus-managed.test.ts and test/cyrus-modpack.test.ts.
import "./_cyrus-server-only-shim";
import { describe, it, afterEach } from "node:test";
import assert from "node:assert/strict";
import { setHost, type CyrusHost, type HostInstallResult } from "../lib/cyrus/host";
import { engineManagedInstaller, MANAGED_REAL_FLAG } from "../lib/cyrus/managed/installer";
import { engineMemberPlacer, MODPACK_REAL_FLAG } from "../lib/cyrus/modpack/engine-placer";
import { realImporterDeps } from "../lib/cyrus/import/deps-real";
import type { CatalogEntry } from "../lib/cyrus/managed/catalog";

type Call = { op: string; a: Record<string, unknown> };
const OK: HostInstallResult = { ok: true, restartRequired: true, changed: ["did it"], notes: ["n"], fileName: "NxeonPackLoader.jar" };
function fakeHost(calls: Call[], result: HostInstallResult = OK) {
  return {
    servers: {
      openFiles: async (userId: string, serverId: string) => { calls.push({ op: "open", a: { userId, serverId } }); return null; },
      pinnedVersion: () => null,
    },
    installs: {
      statePath: "/fake/state.json",
      install: async (a: Record<string, unknown>) => { calls.push({ op: "install", a }); return result; },
      uninstall: async (a: Record<string, unknown>) => { calls.push({ op: "uninstall", a }); return result; },
    },
  } as unknown as CyrusHost;
}
const entry: CatalogEntry = { key: "nxeon-pack-loader", displayName: "Nxeon Pack Loader", family: "1.21", version: "0.1.0", pluginName: "NxeonPackLoader", source: "nxeon-built", sourceRef: "b", sha256: "0".repeat(64), artifact: "a.jar", javaRelease: 21 };
const server = { id: "s1", family: "minecraft", variant: "paper", pinnedVersion: "1.21.11", config: null };
const fs = {} as never;
let restore: (() => void) | null = null;
afterEach(() => { restore?.(); restore = null; });

describe("managed plugins go through host.installs", () => {
  it("install/update pass the prefetched jar, the right mode and the no-download message; remove uninstalls", async () => {
    const calls: Call[] = []; restore = setHost(fakeHost(calls));
    const inst = engineManagedInstaller({ open: async () => ({ fs, server }), readArtifact: async () => Buffer.from("jar"), env: { [MANAGED_REAL_FLAG]: "1" } });
    const r1 = await inst.install({ serverId: "s1", entry, previousVersion: null });
    const r2 = await inst.install({ serverId: "s1", entry, previousVersion: "0.0.9" });
    const r3 = await inst.remove({ serverId: "s1", key: "nxeon-pack-loader", pluginName: "NxeonPackLoader", version: "0.1.0" });
    assert.deepEqual(calls.map((c) => c.op), ["install", "install", "uninstall"]);
    assert.deepEqual(calls.map((c) => c.a.mode), ["install", "update", undefined]);
    const a = calls[0].a as { mod: { source: string; id: string }; resolution: { packages: { prefetched: Buffer; key: string }[] }; noDownloadMessage: string };
    assert.equal(a.mod.source, "nxeon-managed");
    assert.equal(a.mod.id, "managed:nxeon-pack-loader");
    assert.equal(a.resolution.packages[0].key, "nxeon-managed:nxeon-pack-loader");
    assert.deepEqual(a.resolution.packages[0].prefetched, Buffer.from("jar"));
    assert.match(a.noDownloadMessage, /never download/);
    assert.ok(r1.ok && r2.ok && r3.ok);
    assert.deepEqual(r1.ok && r1.notes, ["did it", "n"]);
  });
  it("a host refusal comes back as the install outcome", async () => {
    restore = setHost(fakeHost([], { ok: false, error: "nope" }));
    const inst = engineManagedInstaller({ open: async () => ({ fs, server }), readArtifact: async () => Buffer.from("x"), env: { [MANAGED_REAL_FLAG]: "1" } });
    assert.deepEqual(await inst.install({ serverId: "s1", entry, previousVersion: null }), { ok: false, error: "nope" });
  });
  it("switched off: the host is never called", async () => {
    const calls: Call[] = []; restore = setHost(fakeHost(calls));
    const inst = engineManagedInstaller({ open: async () => ({ fs, server }), env: {} });
    assert.equal((await inst.install({ serverId: "s1", entry, previousVersion: null })).ok, false);
    assert.equal(calls.length, 0);
  });
});

describe("mod pack members go through host.installs", () => {
  it("snapshots the host's state file, places one file per member, uninstalls through the host", async () => {
    const calls: Call[] = []; restore = setHost(fakeHost(calls));
    const written: string[] = [];
    const g = { writeFile: async (p: string) => { written.push(p); }, rename: async () => {}, stat: async () => null, remove: async () => {} } as never;
    const placer = engineMemberPlacer({ fs: g, server, packId: "pk1", env: { [MODPACK_REAL_FLAG]: "1" } });
    assert.deepEqual(placer.statePaths, ["/fake/state.json"]);
    const member = { id: "m1", label: "M One", version: "1.0" } as never;
    await placer.place({ member, files: [{ target: "/opt/mc/plugins/M1.jar", data: Buffer.from("j"), sha256: "a".repeat(64), role: "plugin" }] });
    await placer.remove({ memberId: "m1", targets: [] });
    assert.deepEqual(calls.map((c) => c.op), ["install", "uninstall"]);
    const a = calls[0].a as { mode: string; mod: { id: string; source: string }; noDownloadMessage: string };
    assert.equal(a.mode, "update");
    assert.equal(a.mod.id, "modpack:pk1:m1");
    assert.equal(a.mod.source, "cyrus-modpack");
    assert.match(a.noDownloadMessage, /never download/);
  });
});

describe("import opens servers through host.servers", () => {
  it("delegates openServerReadOnly", async () => {
    const calls: Call[] = []; restore = setHost(fakeHost(calls));
    assert.equal(await realImporterDeps.openServerReadOnly!("u1", "s9"), null);
    assert.deepEqual(calls, [{ op: "open", a: { userId: "u1", serverId: "s9" } }]);
  });
});
EOF
(/opt/nxeon/scripts/devhost test test/cyrus-host-servers.test.ts 2>&1 | grep -E "^# (pass|fail)|not ok|rror" | head -20)

