export type ServerCyrusSummary = { broken: number; outdated: number; failed: number; pendingRestart: number; autoDisabled: number; total: number; worst: "bad" | "warn" | "info" | null; headline: string | null };

export function summarize(rows: CyrusLifecycleRow[]): ServerCyrusSummary {
  const n = (s: string) => rows.filter((r) => r.view.state === s).length;
  const autoDisabled = rows.filter((r) => r.view.state === "disabled" && r.view.notes[0]?.startsWith("We switched it off")).length;
  const s = { broken: n("broken"), outdated: n("outdated"), failed: n("failed"), pendingRestart: n("pending_restart"), autoDisabled, total: rows.length };
  const worst = s.broken || s.failed || s.autoDisabled ? "bad" : s.outdated ? "warn" : s.pendingRestart ? "info" : null;
  const first = (st: string) => rows.find((r) => r.view.state === st)?.name;
  const headline =
    s.broken ? `${first("broken")}${s.broken > 1 ? ` and ${s.broken - 1} more` : ""} ${s.broken > 1 ? "are" : "is"} reporting errors`
    : s.autoDisabled ? `We switched off ${s.autoDisabled === 1 ? "a Cyrus mod" : `${s.autoDisabled} Cyrus mods`} after the game kept crashing`
    : s.failed ? `A change to ${first("failed")} failed`
    : s.outdated ? `${s.outdated === 1 ? `${first("outdated")} is` : `${s.outdated} Cyrus mods are`} out of date`
    : s.pendingRestart ? "Restart to load your Cyrus mod changes"
    : null;
  return { ...s, worst, headline };
}

/** Per-server summaries for a list of servers (server cards). Servers without Cyrus mods are left out. */
export async function summariesForServers(serverIds: string[]): Promise<Map<string, ServerCyrusSummary>> {
  const out = new Map<string, ServerCyrusSummary>();
  if (!serverIds.length) return out;
  const withCyrus = await db.serverMod.findMany({ where: { serverId: { in: serverIds }, mod: { source: CYRUS_SOURCE } }, select: { serverId: true }, distinct: ["serverId"] });
  for (const { serverId } of withCyrus.slice(0, 40)) {
    const rows = await lifecycleForServer(serverId).catch(() => []);
    if (rows.length) out.set(serverId, summarize(rows));
  }
  return out;
}

/* ── installing ─────────────────────────────────────────────────────────── */

/**
 * May `actorId` install this build of someone else's mod? Only PUBLISHED, visible,
 * scanned-not-blocked versions, and only while Setting cyrus_install_published_enabled is on
 * (default OFF: the 2026-10-07 owner decision was "not offered"; the code is ready, the owner
 * decides). The creator's own builds are always allowed.
 */
export async function publicInstallAllowed(build: ModBuild, actorId: string): Promise<boolean> {
  if (build.userId === actorId) return true;
  if (!(await getHost().settings.getBool("cyrus_install_published_enabled", false))) return false;
  if (build.status !== "succeeded" || !build.jarPath || safetyOf(build) === "block") return false;
  const page = await db.cyrusModPage.findUnique({ where: { rootBuildId: build.rootBuildId ?? build.id } });
  if (!page || page.visibility !== "PUBLIC" || page.hiddenAt) return false;
  // Same flag as lib/cyrus-mods/gate.ts (not imported: that module pulls in next/* + auth, and the worker uses this file).
  return getHost().settings.getBool("cyrus_mods_public_enabled", false).catch(() => false);
}

export type ServerPlan = { server: { id: string; name: string; status: string; variant: string | null; version: string | null }; plan: InstallPlan };

/** One install plan per server the actor owns that runs the mod's game. */
export async function installPlansFor(build: ModBuild, actorId: string): Promise<{ game: string; plans: ServerPlan[] }> {
  const gameId = "minecraft"; // ModBuild is Minecraft-only today; other games join through GameSupport.
  const support = supportFor(gameId)!;
  const root = build.rootBuildId ?? build.id;
  const chain = (await chainsFor([root])).get(root) ?? [];
  const builtFor = [...new Set(succeededVersions(chain).map((b) => b.mcVersion))];
  const servers = await db.server.findMany({ where: { userId: actorId, status: { notIn: ["DELETING"] } }, include: { osTemplate: true, gamePlan: true }, orderBy: { createdAt: "asc" } });
  const gm = await db.gameMod.findFirst({ where: { source: CYRUS_SOURCE, sourceId: root }, select: { id: true } });
  const existing = gm ? await db.serverMod.findMany({ where: { modId: gm.id, serverId: { in: servers.map((s) => s.id) } } }) : [];
  const plans: ServerPlan[] = [];
  for (const s of servers) {
    if (familyFor(s) !== "minecraft") continue;
    const variant = (s.gameVariant || "vanilla").toLowerCase();
    const version = await serverGameVersion(s);
    const ex = existing.find((e) => e.serverId === s.id);
    const ps: PlanServer = {
      id: s.id,
      name: s.label || s.hostname,
      sameGame: true,
      variantOk: CYRUS_VARIANTS.includes(variant),
      variantNote: `Runs ${variant[0].toUpperCase() + variant.slice(1)}; Cyrus plugins need Paper or Purpur (switch it in the server's Settings).`,
      running: s.status === "RUNNING",
      version,
      existing: ex && ex.status !== "REMOVED" ? { status: ex.status, buildId: ex.versionId } : null,
    };
    const plan = buildInstallPlan(support, { name: chain.length ? displayName(chain) : (build.pluginName ?? "This mod"), buildId: build.id, target: build.mcVersion, builtFor, installable: true, safety: safetyOf(build) }, ps);
    plans.push({ server: { id: s.id, name: ps.name, status: s.status, variant, version }, plan });
  }
  return { game: support.name, plans };
}

export type CreatorAlertView = {
  id: string; kind: string; title: string; body: string; servers: number; targetVersion: string | null; buildable: boolean;
  modTitle: string; pageSlug: string | null; updateHref: string | null; firstSeenAt: string; lastSeenAt: string;
};

export async function toAlertViews(rows: CyrusCreatorAlert[]): Promise<CreatorAlertView[]> {
  const roots = [...new Set(rows.map((r) => r.rootBuildId))];
  const [pages, chains] = await Promise.all([
    db.cyrusModPage.findMany({ where: { rootBuildId: { in: roots } }, select: { rootBuildId: true, slug: true, title: true } }),
    chainsFor(roots),
  ]);
  return rows.map((r) => {
    const p = pages.find((x) => x.rootBuildId === r.rootBuildId);
    const chain = chains.get(r.rootBuildId) ?? [];
    // The refine path continues from the mod's CURRENT version (the creator's restored head, else the newest).
    const head = chainHead(chain)?.id ?? r.rootBuildId;
    return {
      id: r.id, kind: r.kind, title: r.title, body: r.body, servers: r.servers, targetVersion: r.targetVersion, buildable: r.buildable,
      modTitle: p?.title ?? (chain.length ? displayName(chain) : "Your Cyrus mod"),
      pageSlug: p?.slug ?? null,
      updateHref: r.buildable || r.kind === "ERROR_REPORTS" ? updateWithCyrusHref(head, r.buildable ? r.targetVersion : null) : null,
      firstSeenAt: r.firstSeenAt.toISOString(), lastSeenAt: r.lastSeenAt.toISOString(),
    };
  });
}

