async function eligible(c: GrantCtx): Promise<boolean> {
  const cfg = await loadTokenConfig();
  // Only servers of a game Cyrus builds for (registry status "live") earn tokens.
  const fam = c.gameFamily ?? (await db.server.findUnique({ where: { id: c.serverId }, select: { gamePlan: { select: { gameFamily: true } } } }))?.gamePlan?.gameFamily ?? null;
