cd /tank/dev-worktrees/cyrus-r22; cat > test/cyrus-db-seam.test.ts <<'EOF'
// cyrusDb: the one door to Cyrus' own tables. It follows whichever host is active, and Nxeon's tables are not on its type.
import "./_cyrus-server-only-shim";
import { describe, it, afterEach } from "node:test";
import assert from "node:assert/strict";
import { cyrusDb } from "../lib/cyrus/db";
import { setHost, getHost, type CyrusHost } from "../lib/cyrus/host";

let restore: (() => void) | null = null;
afterEach(() => { restore?.(); restore = null; });

describe("cyrusDb", () => {
  it("resolves through the active host on every use (setHost takes effect, restore puts the old one back)", async () => {
    const seen: string[] = [];
    const fake = { cyrusPlan: { findUnique: async (a: unknown) => { seen.push(JSON.stringify(a)); return { userId: "u1" }; } }, $transaction: async (f: (tx: unknown) => unknown) => f("TX") };
    const before = getHost().db;
    restore = setHost({ db: fake } as unknown as CyrusHost);
    assert.deepEqual(await cyrusDb.cyrusPlan.findUnique({ where: { userId: "u1" } }), { userId: "u1" });
    assert.equal(await cyrusDb.$transaction(async (tx) => tx as unknown), "TX");
    assert.deepEqual(seen, ['{"where":{"userId":"u1"}}']);
    restore(); restore = null;
    assert.equal(getHost().db, before);
  });
  it("writes (test doubles) land on the active host's client", () => {
    const fake: Record<string, unknown> = {};
    restore = setHost({ db: fake } as unknown as CyrusHost);
    (cyrusDb as unknown as Record<string, unknown>).cyrusPlan = "stub";
    assert.equal(fake.cyrusPlan, "stub");
  });
  it("platform tables are not on the type", () => {
    // Compile-time checks (tsc): these lines fail to type-check if a platform table ever becomes reachable.
    const probe = (): void => {
      // @ts-expect-error User is the platform's
      void cyrusDb.user;
      // @ts-expect-error Server is the platform's
      void cyrusDb.server;
      // @ts-expect-error Setting is the platform's
      void cyrusDb.setting;
      // @ts-expect-error AuditLog is the platform's
      void cyrusDb.auditLog;
      // @ts-expect-error ServerMod is the platform's
      void cyrusDb.serverMod;
      void cyrusDb.modBuild; void cyrusDb.cyrusPlan; // Cyrus' own: fine
    };
    assert.equal(typeof probe, "function");
  });
});
EOF
(/opt/nxeon/scripts/devhost test test/cyrus-db-seam.test.ts 2>&1 | grep -E "^# (pass|fail)|not ok"); (/opt/nxeon/scripts/devhost tsc 2>&1 | head)

